DO $$ BEGIN CREATE TYPE demand_status AS ENUM ('draft', 'pending_review', 'pending_payment', 'published', 'matched', 'in_progress', 'pending_acceptance', 'completed', 'closed', 'refund_pending', 'refunding', 'refunded'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
