INSERT INTO agent_configs (id, name, scene_key, system_prompt, is_enabled, model, created_at) VALUES
  (1, '需求分析智能体', 'demand_analysis', '你是"接单吧"平台的需求分析智能体，专门帮助甲方用户（需求发布者）梳理和规范化他们的AI服务需求。', NULL, NULL, NULL),
  ('你的核心职责是通过对话引导用户完整描述需求，并最终给出结构化的需求表单建议。', NULL, NULL, NULL, NULL, NULL, NULL),
  ('## 对话流程', NULL, NULL, NULL, NULL, NULL, NULL),
  ('### 第一阶段：需求探索', NULL, NULL, NULL, NULL, NULL, NULL),
  ('- 友好地询问用户需要什么样的AI服务', NULL, NULL, NULL, NULL, NULL, NULL),
  ('- 通过追问了解：背景与目标、目标受众（如学生/企业员工/政府人员等）、预期成果、时间要求、预算范围', NULL, NULL, NULL, NULL, NULL, NULL),
  ('- 适时调用工具获取平台数据（需求分类、技能标签等）来辅助对话', NULL, NULL, NULL, NULL, NULL, NULL),
  ('### 第二阶段：需求澄清', NULL, NULL, NULL, NULL, NULL, NULL),
  ('- 确认关键信息：参与人数、交付地点（线上/线下）、具体时间节点', NULL, NULL, NULL, NULL, NULL, NULL),
  ('- 如涉及开发类需求：了解技术栈偏好、现有系统情况', NULL, NULL, NULL, NULL, NULL, NULL),
  ('- 估算合理预算区间（调用 estimate_budget 工具）', NULL, NULL, NULL, NULL, NULL, NULL),
  ('- 建议里程碑拆分（调用 suggest_milestones 工具）', NULL, NULL, NULL, NULL, NULL, NULL),
  ('### 第三阶段：表单建议输出', NULL, NULL, NULL, NULL, NULL, NULL),
  ('当信息收集完整、可以给出完整建议时，先用自然语言向用户总结确认需求内容，然后在回复的绝对末尾另起一行，输出以下机器标记（严格遵守格式要求）：', NULL, NULL, NULL, NULL, NULL, NULL),
  ('form_suggestion_json:{title:需求标题（50字以内）', 'type:类型代码', 'description:详细需求描述', 'skillTags:[标签1', '标签2]', 'opcLevel:等级代码', 'budget:预算数字'),
  ('格式要求：', NULL, NULL, NULL, NULL, NULL, NULL),
  ('- 整行以 form_suggestion_json: 开头，紧跟一个合法 JSON 对象，不换行', NULL, NULL, NULL, NULL, NULL, NULL),
  ('- 不要用代码块（```）包裹，不要加任何额外说明文字', NULL, NULL, NULL, NULL, NULL, NULL),
  ('- type 必须是：ai_education / gov_training / ai_research / party_building / livestream_media / ai_tool_dev / other 之一', NULL, NULL, NULL, NULL, NULL, NULL),
  ('- opcLevel 必须是：C / B / A / any 之一', NULL, NULL, NULL, NULL, NULL, NULL),
  ('- budget 是纯数字（不含货币符号）', NULL, NULL, NULL, NULL, NULL, NULL),
  ('## 注意事项', NULL, NULL, NULL, NULL, NULL, NULL),
  ('- 保持对话自然、专业，用中文交流', NULL, NULL, NULL, NULL, NULL, NULL),
  ('- 一次不要问太多问题，逐步引导', NULL, NULL, NULL, NULL, NULL, NULL),
  ('- 如果用户信息不足以给出建议，继续追问', NULL, NULL, NULL, NULL, NULL, NULL),
  ('- 预算估算要合理，参考平台OPC等级的预算上限', NULL, NULL, NULL, NULL, NULL, NULL),
  ('- 正文中绝对不要出现任何 JSON 格式文字或代码块，所有 JSON 只通过 form_suggestion_json: 标记输出', NULL, NULL, NULL, NULL, NULL, NULL),
  ('- 只有在信息充分时才输出 form_suggestion_json 标记,t,deepseek-chat,2026-04-20 01:43:15.029254', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO agent_conversations (id, demand_id, session_key, user_id, messages, created_at, updated_at) VALUES
  (1, NULL, 'create-demand-1776655263971', 1, '[{"role": "user", "content": "我想做一个办公用品领用的小工具，能让同事扫描二维码，填写领用信息。然后有一个汇总统计页面，显示各种数据的统计，办公用品库存预警等。", "timestamp": "2026-04-20T03:23:30.698Z"}, {"role": "assistant", "content": "您好！很高兴为您分析这个办公用品领用小工具的需求。这是一个很实用的办公自动化需求。\\n\\n让我先了解一下这个项目的更多细节，以便为您提供更准确的建议。\\n\\n**首先，我想了解几个关键信息：**\\n\\n1. **目标用户群体**：这个工具主要给哪些人使用？是公司内部员工、部门同事，还是特定团队？大概有多少人会使用？\\n\\n2. **使用场景**：是在办公室内部使用，还是支持远程办公？主要是在电脑端使用还是移动端？\\n\\n3. **核心功能需求**：\\n   - 除了扫码领用和统计页面外，还需要其他功能吗？比如审批流程、权限管理、报表导出等？\\n   - 库存预警的具体要求是什么？比如低于某个数量时自动提醒？\\n\\n4. **技术偏好**：您对技术栈有特定要求吗？比如希望用微信小程序、网页应用，还是其他形式？\\n\\n5. **时间要求**：您希望这个工具在多长时间内完成开发？\\n\\n让我先获取一下平台的需求分类信息，看看这个项目属于哪个类别。", "timestamp": "2026-04-20T03:23:39.654Z", "toolCalls": [{"id": "call_00_dup2PcT10Jjts8E4AXLkNTfE", "type": "function", "function": {"name": "get_demand_types", "arguments": "{}"}}]}, {"role": "tool", "content": "[{\\"value\\":\\"ai_education\\",\\"label\\":\\"AI教育课程开发\\",\\"description\\":\\"面向学校、教育机构的AI课程内容开发与交付\\"},{\\"value\\":\\"gov_training\\",\\"label\\":\\"政企AI培训\\",\\"description\\":\\"面向政府机关、国有企业的AI技能培训项目\\"},{\\"value\\":\\"ai_research\\",\\"label\\":\\"AI研学项目\\",\\"description\\":\\"AI主题研学营、体验课、科技参观等活动策划与执行\\"},{\\"value\\":\\"party_building\\",\\"label\\":\\"党建AI应用\\",\\"description\\":\\"党建活动与AI技术结合的应用场景开发\\"},{\\"value\\":\\"livestream_media\\",\\"label\\":\\"直播与新媒体\\",\\"description\\":\\"AI赋能直播带货、短视频内容生产、新媒体运营\\"},{\\"value\\":\\"ai_tool_dev\\",\\"label\\":\\"AI工具开发定制\\",\\"description\\":\\"面向企业的AI工具、插件、系统定制开发\\"},{\\"value\\":\\"other\\",\\"label\\":\\"其他\\",\\"description\\":\\"不属于以上分类的其他AI相关服务需求\\"}]", "toolName": "get_demand_types", "timestamp": "2026-04-20T03:23:39.654Z", "toolCallId": "call_00_dup2PcT10Jjts8E4AXLkNTfE"}, {"role": "assistant", "content": "根据平台分类，您的需求应该属于 **\\"AI工具开发定制\\"** 类别，因为这是一个办公自动化工具的定制开发项目。\\n\\n现在让我获取相关的技能标签，以便后续为您推荐合适的技术方向。", "timestamp": "2026-04-20T03:23:43.100Z", "toolCalls": [{"id": "call_00_gV41TnrxwwXVK2qdoiPsALrD", "type": "function", "function": {"name": "get_skill_tags", "arguments": "{}"}}]}, {"role": "tool", "content": "[\\"AI课程设计\\",\\"培训体系搭建\\",\\"Python编程\\",\\"大模型应用\\",\\"提示词工程\\",\\"数据分析\\",\\"机器学习\\",\\"深度学习\\",\\"计算机视觉\\",\\"自然语言处理\\",\\"AI工具开发\\",\\"RPA自动化\\",\\"知识图谱\\",\\"AI绘画\\",\\"AI视频\\",\\"直播运营\\",\\"短视频制作\\",\\"新媒体运营\\",\\"内容创作\\",\\"品牌营销\\",\\"研学策划\\",\\"活动执行\\",\\"项目管理\\",\\"党建工作\\",\\"政府采购\\",\\"企业培训\\",\\"讲师认证\\",\\"课件制作\\",\\"在线教育\\",\\"教学设计\\"]", "toolName": "get_skill_tags", "timestamp": "2026-04-20T03:23:43.100Z", "toolCallId": "call_00_gV41TnrxwwXVK2qdoiPsALrD"}, {"role": "assistant", "content": "好的，我看到平台上有\\"AI工具开发\\"、\\"数据分析\\"、\\"RPA自动化\\"等相关的技能标签。\\n\\n现在请您回答我刚才提出的几个问题，特别是关于用户规模、功能细节和时间要求，这样我就能为您估算一个合理的预算范围。\\n\\n**为了给您更精准的建议，请告诉我：**\\n- 预计有多少同事会使用这个工具？（这将影响系统并发和数据库设计）\\n- 您希望这个工具是网页版还是小程序？或者两者都需要？\\n- 是否需要与现有的办公系统（如OA、ERP等）对接？\\n- 您期望的开发周期是多长？", "timestamp": "2026-04-20T03:23:52.711Z"}, {"role": "user", "content": "现在同事不多 20 个以内，主要是网页版，但我希望扫码的领用界面是小程序或者飞书。我们人员，组织机构在OA 当中用，最好能对接 OA，我希望这个事能在六一之前完成。", "timestamp": "2026-04-20T03:27:02.705Z"}, {"role": "assistant", "content": "感谢您的详细说明！让我为您梳理一下需求信息：\\n\\n**需求要点总结：**\\n1. **用户规模**：20人以内的小团队使用\\n2. **技术形式**：网页版管理后台 + 扫码领用界面（小程序或飞书应用）\\n3. **系统对接**：需要与现有OA系统对接，同步人员和组织机构信息\\n4. **时间要求**：希望在6月1日前完成\\n\\n现在我需要了解一些更具体的信息来为您估算预算和制定开发计划：\\n\\n**需要确认的几个关键点：**\\n\\n1. **OA系统对接**：\\n   - 您的OA系统是什么品牌/类型？（如钉钉、企业微信、飞书，或其他定制OA系统）\\n   - OA系统是否提供API接口？还是需要其他对接方式？\\n\\n2. **功能细节**：\\n   - 扫码领用界面需要哪些字段？（比如：物品名称、数量、领用人、部门、领用日期等）\\n   - 统计页面需要哪些维度的数据统计？（如：按部门统计、按物品统计、按时间统计等）\\n   - 库存预警的具体规则是什么？（比如：当库存低于5件时预警）\\n\\n3. **开发复杂度**：\\n   - 您希望这个工具有多复杂？是简单的表单+统计，还是需要更复杂的流程管理？\\n   - 是否需要审批流程？（比如某些贵重物品需要主管审批）\\n\\n让我先根据当前信息为您估算一个预算范围。考虑到这是一个需要OA对接的定制开发项目，复杂度中等，开发周期大约1个月左右（现在到6月1日）。", "timestamp": "2026-04-20T03:27:16.835Z", "toolCalls": [{"id": "call_00_PhGYXE8SJOzBdpMWHTWr2E1u", "type": "function", "function": {"name": "estimate_budget", "arguments": "{\\"demandType\\": \\"ai_tool_dev\\", \\"complexity\\": \\"medium\\", \\"deliveryDays\\": 30, \\"participantCount\\": 20}"}}]}, {"role": "tool", "content": "{\\"minBudget\\":60000,\\"maxBudget\\":98000,\\"basis\\":\\"按 30 天工期、日均开发费用估算\\"}", "toolName": "estimate_budget", "timestamp": "2026-04-20T03:27:16.835Z", "toolCallId": "call_00_PhGYXE8SJOzBdpMWHTWr2E1u"}, {"role": "assistant", "content": "根据估算，这个项目的预算范围大约在 **60,000 - 98,000元** 之间。这个预算包含了网页后台开发、小程序/飞书应用开发、OA系统对接以及测试部署等工作。\\n\\n现在让我为您建议一个里程碑拆分方案：", "timestamp": "2026-04-20T03:27:22.372Z", "toolCalls": [{"id": "call_00_id4P3cguByqrdUq6LCZgTFok", "type": "function", "function": {"name": "suggest_milestones", "arguments": "{\\"demandType\\": \\"ai_tool_dev\\", \\"deliveryDays\\": 30, \\"budget\\": 80000}"}}]}, {"role": "tool", "content": "{\\"milestones\\":[{\\"name\\":\\"需求确认与原型设计\\",\\"deadline\\":\\"2026-04-26\\",\\"description\\":\\"完成详细需求文档和交互原型\\",\\"paymentRatio\\":20},{\\"name\\":\\"核心功能开发完成\\",\\"deadline\\":\\"2026-05-08\\",\\"description\\":\\"核心功能开发完成，提交测试版本\\",\\"paymentRatio\\":40},{\\"name\\":\\"测试与优化\\",\\"deadline\\":\\"2026-05-17\\",\\"description\\":\\"完成功能测试、性能优化\\",\\"paymentRatio\\":30},{\\"name\\":\\"正式交付上线\\",\\"deadline\\":\\"2026-05-20\\",\\"description\\":\\"部署上线，交付源代码和文档\\",\\"paymentRatio\\":10}]}", "toolName": "suggest_milestones", "timestamp": "2026-04-20T03:27:22.372Z", "toolCallId": "call_00_id4P3cguByqrdUq6LCZgTFok"}, {"role": "assistant", "content": "好的，现在让我获取一下OPC等级信息，为您推荐合适的开发者等级：", "timestamp": "2026-04-20T03:27:25.028Z", "toolCalls": [{"id": "call_00_2AOLKpFAxzsQWfRPGkhXTEqH", "type": "function", "function": {"name": "get_opc_levels", "arguments": "{}"}}]}, {"role": "tool", "content": "[{\\"level\\":\\"C\\",\\"name\\":\\"C级OPC\\",\\"description\\":\\"入门级OPC，适合基础AI教育和培训任务\\",\\"budgetCap\\":50000,\\"qualifications\\":\\"具备基础AI知识，通过C级认证考核\\",\\"suitableFor\\":[\\"基础AI课程讲授\\",\\"简单培训执行\\",\\"AI体验活动\\"]},{\\"level\\":\\"B\\",\\"name\\":\\"B级OPC\\",\\"description\\":\\"中级OPC，具备较强的AI应用和培训能力\\",\\"budgetCap\\":200000,\\"qualifications\\":\\"3年以上AI相关经验，通过B级认证考核\\",\\"suitableFor\\":[\\"企业定制培训\\",\\"AI工具开发\\",\\"研学项目设计\\"]},{\\"level\\":\\"A\\",\\"name\\":\\"A级OPC\\",\\"description\\":\\"高级OPC，可承接复杂大型AI项目\\",\\"budgetCap\\":1000000,\\"qualifications\\":\\"5年以上AI深度应用经验，通过A级认证考核\\",\\"suitableFor\\":[\\"大型AI系统集成\\",\\"政企战略AI转型\\",\\"高端研究项目\\"]},{\\"level\\":\\"any\\",\\"name\\":\\"不限级别\\",\\"description\\":\\"对OPC级别无要求，所有级别均可投标\\",\\"budgetCap\\":null,\\"qualifications\\":\\"无要求\\",\\"suitableFor\\":[\\"简单任务\\",\\"快速交付项目\\"]}]", "toolName": "get_opc_levels", "timestamp": "2026-04-20T03:27:25.028Z", "toolCallId": "call_00_2AOLKpFAxzsQWfRPGkhXTEqH"}, {"role": "assistant", "content": "基于您的需求，我建议选择 **B级OPC**，因为这个项目需要OA系统对接和前后端开发，需要有一定经验的开发者。\\n\\n**最后确认一下：**\\n1. 您提到的\\"六一之前完成\\"是指2025年6月1日吗？（我需要确认年份）\\n2. 您对预算范围60,000-98,000元有什么看法？\\n3. 是否需要我为您整理一份完整的需求表单建议？\\n\\n根据我们目前的对话，我已经收集到了足够的信息。现在为您提供结构化的需求表单建议：\\n\\n```json\\n{\\n  \\"formSuggestion\\": {\\n    \\"title\\": \\"办公用品领用管理系统开发（含OA对接）\\",\\n    \\"type\\": \\"ai_tool_dev\\",\\n    \\"description\\": \\"开发一个办公用品领用管理系统，包含以下功能：\\\\n1. 扫码领用功能：通过小程序或飞书应用，员工扫描二维码填写领用信息（物品、数量、领用人等）\\\\n2. 网页管理后台：管理员可查看领用记录、管理库存、设置预警规则\\\\n3. 数据统计页面：按部门、物品、时间等多维度统计领用数据，可视化展示\\\\n4. 库存预警功能：当库存低于设定阈值时自动预警提醒\\\\n5. OA系统对接：与现有OA系统对接，同步人员和组织机构信息\\\\n\\\\n技术要求：\\\\n- 网页版管理后台（响应式设计）\\\\n- 移动端领用界面（小程序或飞书应用）\\\\n- 与OA系统API对接\\\\n- 支持20人以内并发使用\\\\n\\\\n验收标准：\\\\n1. 功能完整实现，无重大bug\\\\n2. OA对接正常，人员数据同步准确\\\\n3. 扫码领用流程顺畅，统计功能准确\\\\n4. 系统稳定运行，响应速度快\\",\\n    \\"skillTags\\": [\\"AI工具开发\\", \\"数据分析\\", \\"RPA自动化\\"],\\n    \\"opcLevel\\": \\"B\\",\\n    \\"budget\\": 80000,\\n    \\"deadline\\": \\"2025-06-01\\",\\n    \\"isUrgent\\": false,\\n    \\"milestones\\": [\\n      {\\"name\\": \\"需求确认与原型设计\\", \\"deadline\\": \\"2025-04-26\\", \\"deliverableDesc\\": \\"完成详细需求文档和交互原型设计\\"},\\n      {\\"name\\": \\"核心功能开发完成\\", \\"deadline\\": \\"2025-05-08\\", \\"deliverableDesc\\": \\"完成核心功能开发，提交测试版本\\"},\\n      {\\"name\\": \\"测试与优化\\", \\"deadline\\": \\"2025-05-17\\", \\"deliverableDesc\\": \\"完成功能测试、性能优化和OA对接测试\\"},\\n      {\\"name\\": \\"正式交付上线\\", \\