  (6, '大模型微调策略与实战', 'tech', 'B', 405, '掌握LoRA、QLoRA等主流微调方法，结合实际业务场景落地', NULL, NULL, 856, 'f', '2026-03-25 06:28:03.291533', 'draft', 0, NULL, NULL, NULL, '2026-04-09 06:08:50.302'),
  (5, '面向政企的提示词工程进阶', 'tech', 'A', 260, '政企场景下Prompt设计实战，提升合规性与容错率', 'A级必修', 4.9, 1267, 'f', '2026-03-25 06:28:03.291533', 'published', 2499, NULL, '张锦华', NULL, '2026-04-01 04:44:12.622'),
  (14, '政企AI专题课', 'strategy', 'A', 300, '面向政府官员、企业高管、党务工作者等群体的定制化培训课程。', '定制/领导力/认知升级', NULL, 40, 'f', '2026-04-01 15:34:07.176814', 'published', 9999, NULL, '刘老师', 20, '2026-04-01 15:37:07.625'),
  (10, 'L1-AI素养通识', 'tech', 'C', 480, '此课程为必修课，学习考核通过可直接获得C级认证，并解锁接单权限。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('目标学员：非IT人士、职场转型者、OPC新人、对AI感兴趣的各行各业从业者。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('培养目标：掌握主流AI工具的使用方法，能够在日常工作中有效运用AI提升效率。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (',AI素养/通识,,55,t,2026-04-01 15:17:00.754739,published,1200,/api/storage/objects/uploads/6601ce29-6e58-40b7-a582-fe89e7c39a0e,韩老师,30,2026-04-09 07:02:22.826', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
