  (5, 'JDB-202603-0005', '企业直播带货方案策划', 'livestream_media', '为某电商企业策划AI赋能的直播带货方案，包含直播脚本、话术设计、AI工具配置方案。需了解直播行业和AI工具应用。', '["直播运营", "文案撰写", "AI应用开发", "短视频制作"]', 'B', 20000, '2026-04-18', '[{"name": "方案策划", "deadline": "2026-04-10", "deliverableDesc": "完成直播方案全案"}, {"name": "话术与脚本", "deadline": "2026-04-18", "deliverableDesc": "完成直播话术和脚本模板"}]', 'open', 'published', 't', '2026-04-05 18:00:00', 1, '[]', '2026-03-24 03:24:59.688971', '2026-03-24 03:24:59.688971', '[]', NULL),
  (8, 'JDB-202603-0008', 'AI提示词工程培训课件开发', 'ai_education', '开发一套AI提示词工程培训课件（8学时），面向OPC社区成员。内容需涵盖提示词基础、高级技巧、实际应用案例。', '["课件制作", "提示词工程", "教案设计", "PPT设计"]', 'B', 18000, '2026-04-28', '[{"name": "课程大纲", "deadline": "2026-04-15", "deliverableDesc": "完成课程大纲和教学目标"}, {"name": "课件成品", "deadline": "2026-04-28", "deliverableDesc": "完成全部PPT课件和教案"}]', 'open', 'published', 'f', '2026-04-12 18:00:00', 1, '[]', '2026-03-24 03:24:59.688971', '2026-03-24 03:24:59.688971', '[]', NULL),
  (1, 'JDB-202603-0001', 'AI教育课程体系开发', 'ai_education', '为某市教育局开发K12阶段AI教育课程体系，包含教学大纲、课件、实践案例，共6个模块。需要有AI教育行业经验，熟悉课程设计方法论。', '["课件制作", "教案设计", "AI应用开发", "PPT设计"]', 'A', 80000, '2026-05-15', '[{"name": "课程大纲设计", "deadline": "2026-04-10", "deliverableDesc": "完成6模块课程大纲"}, {"name": "课件制作", "deadline": "2026-04-30", "deliverableDesc": "完成全部课件PPT"}, {"name": "实践案例开发", "deadline": "2026-05-15", "deliverableDesc": "完成配套实践案例"}]', 'open', 'published', 'f', '2026-04-05 18:00:00', 1, '[]', '2026-03-24 03:24:59.688971', '2026-03-24 03:24:59.688971', '[{"url": "#", "name": "需求说明书_v1.2.pdf", "size": "2.4 MB", "type": "pdf"}, {"url": "#", "name": "企业背景及培训目标.docx", "size": "1.1 MB", "type": "doc"}, {"url": "#", "name": "往期课程样本.zip", "size": "18.6 MB", "type": "archive"}, {"url": "#", "name": "学员数据统计表.xlsx", "size": "560 KB", "type": "spreadsheet"}]', NULL),
  (2, 'JDB-202603-0002', '政企AI培训方案设计与授课', 'gov_training', '为某区政府部门设计AI应用培训方案，包含理论课程和实操环节。培训对象为政府工作人员，需通俗易懂。共2天培训，含课件+现场授课。', '["教案设计", "PPT设计", "AI应用开发", "提示词工程"]', 'B', 25000, '2026-04-20', '[{"name": "培训方案设计", "deadline": "2026-04-08", "deliverableDesc": "完成培训大纲和日程安排"}, {"name": "课件交付", "deadline": "2026-04-15", "deliverableDesc": "完成全部培训课件"}]', 'open', 'published', 't', '2026-04-01 18:00:00', 1, '[]', '2026-03-24 03:24:59.688971', '2026-03-24 03:24:59.688971', '[{"url": "#", "name": "党建活动策划方案参考.pdf", "size": "3.2 MB", "type": "pdf"}, {"url": "#", "name": "往年活动照片集.zip", "size": "42.1 MB", "type": "archive"}, {"url": "#", "name": "预算明细表.xlsx", "size": "320 KB", "type": "spreadsheet"}]', NULL),
  (3, 'JDB-202603-0003', 'AI研学基地宣传视频制作', 'ai_research', '为原点AI研学基地制作3分钟宣传视频，包含基地介绍、课程亮点、学员体验等内容。需要前期策划脚本+拍摄+后期剪辑。', '["视频剪辑", "短视频制作", "文案撰写"]', 'B', 15000, '2026-04-25', '[{"name": "脚本策划", "deadline": "2026-04-10", "deliverableDesc": "完成视频脚本和分镜"}, {"name": "成片交付", "deadline": "2026-04-25", "deliverableDesc": "完成最终成片"}]', 'open', 'published', 'f', '2026-04-08 18:00:00', 1, '[]', '2026-03-24 03:24:59.688971', '2026-03-24 03:24:59.688971', '[{"url": "#", "name": "直播间现状评估报告.pdf", "size": "5.8 MB", "type": "pdf"}, {"url": "#", "name": "竞品分析截图.zip", "size": "12.3 MB", "type": "archive"}, {"url": "#", "name": "品牌VI规范手册.pdf", "size": "8.9 MB", "type": "pdf"}]', NULL),
  (6, 'JDB-202603-0006', 'AI智能客服系统定制开发', 'ai_tool_dev', '为企业客户定制AI智能客服系统，支持多轮对话、知识库管理、工单生成。需要LLM集成经验和Web开发能力。', '["AI应用开发", "Web开发", "提示词工程", "数据处理"]', 'A', 100000, '2026-06-15', '[{"name": "系统设计", "deadline": "2026-04-20", "deliverableDesc": "完成系统架构设计和技术方案"}, {"name": "核心开发", "deadline": "2026-05-20", "deliverableDesc": "完成核心对话引擎开发"}, {"name": "集成测试", "deadline": "2026-06-15", "deliverableDesc": "完成系统集成和测试"}]', 'open', 'matched', 'f', '2026-04-10 18:00:00', 1, '[]', '2026-03-24 03:24:59.688971', '2026-04-01 08:39:43.259', '[]', NULL),
  (4, 'JDB-202603-0004', '党建AI应用小程序开发', 'party_building', '开发一款党建学习AI助手小程序，支持知识问答、学习计划推荐、在线测试等功能。需要有小程序开发经验和AI集成能力。', '["小程序开发", "AI应用开发", "Web开发"]', 'A', 120000, '2026-06-30', '[{"name": "需求分析与原型", "deadline": "2026-04-30", "deliverableDesc": "完成需求文档和原型设计"}, {"name": "核心功能开发", "deadline": "2026-05-31", "deliverableDesc": "完成核心功能开发"}, {"name": "测试与上线", "deadline": "2026-06-30", "deliverableDesc": "完成测试并上线"}]', 'open', 'matched', 'f', '2026-04-15 18:00:00', 1, '[]', '2026-03-24 03:24:59.688971', '2026-03-31 15:21:00.212', '[]', NULL),
  (7, 'JDB-202603-0007', '社区运营数据分析报告', 'other', '对OPC社区过去6个月的运营数据进行分析，产出数据分析报告，包含用户活跃度、订单转化率、收入趋势等分析维度。', '["数据处理", "PPT设计", "文案撰写"]', 'C', 5000, '2026-04-12', '[]', 'open', 'matched', 'f', '2026-04-08 18:00:00', 1, '[]', '2026-03-24 03:24:59.688971', '2026-04-08 10:39:23.791', '[]', NULL),
  (17, 'JDB-20260330-0001', 'TEST', 'ai_education', '发哈附件卡号多少分', '["AI应用开发", "Vibe Coding"]', 'A', 28000, '2026-05-09', '[{"name": "预交付", "deadline": "2026-04-09T00:00:00.000Z", "deliverableDesc": "交付原型"}, {"name": "正式交付", "deadline": "2026-05-07T00:00:00.000Z", "deliverableDesc": "正式上线"}]', 'open', 'closed', 't', '2026-04-01 00:00:00', 11, '[]', '2026-03-30 06:53:33.488447', '2026-03-30 06:54:04.41', '[]', NULL),
  (20, 'JDB-20260330-0002', '湖南省旅游数智人才培养项目核心课程体系开发与教学资源包制作', 'ai_education', '本需求为"湖南省旅游数智人才队伍建设"项目（总预算100万元/20人/1年培养周期）的前置课程开发工作。项目已完成实施方案编制（V9版），明确了"理论筑基、实操赋能、参访研学、岗位历练、课题攻坚"五大培养模块及一年期课程表框架，现需委托专业团队将课程框架细化为可直接交付授课的完整教学资源包，涵盖课件、实操手册、案例库及考核工具等全套教学物料。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('工作范围：', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('（1）课程体系细化设计。基于方案V9版一年期课程表（含AI基础认知、提示词工程、政策合规、数据可视化、多模态转化、智能服务、数字营销、课题攻坚等模块），完成每门课程的教学大纲编写，包括：课程目标、知识点拆解、教学方法设计、课时分配、考核要点等，合计不少于12门课程的完整大纲。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('（2）核心课件制作。针对第一、二季度的8门理论与实操课程（AI全景认知与基础应用、提示词工程与精准控制、旅游数智化政策解读与合规管理、AI科研工具入门与数据清洗、旅游数据可视化工具应用、科研/宣传成果多模态创作、智慧旅游服务工具操作维护、AI驱动的旅游营销方案设计），制作标准化授课PPT课件，每门课件不少于40页，配套讲师授课指南（含教学话术要点、互动环节设计、时间分配建议）。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('（3）实操手册与案例库开发。编写配套实操训练手册，覆盖Prompt设计实训、AI科研工具操作、Echarts/Tableau数据看板搭建、Midjourney/Runway多模态创作等核心技能模块，每个模块须包含不少于3个旅游行业实操案例（如张家界景区游客数据可视化、湖南红色旅游AI宣传素材生成等），案例须可直接用于课堂实训。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('（4）考核评估工具包。设计结业考核方案与配套评分工具，包括：各模块实操测试题库（不少于60题）、课题攻坚评审评分表、岗位历练鉴定模板、学员综合能力评估量表，确保考核指标与方案中实操测试通过率≥95%、结业成果优秀率≥30%等绩效要求对齐。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('交付物清单：', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('① 《课程体系教学大纲汇编》（Word格式，含12门课程完整大纲）×1份；', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('② 标准化授课PPT课件（8门核心课程，每门≥40页）×8套；', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('③ 《讲师授课指南》（Word格式，8门课程配套）×1份；', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('④ 《实操训练手册》（Word格式，含各模块操作步骤与旅游行业案例，≥15', '000字）×1份；', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('⑤ 《旅游数智化教学案例库》（独立成册，不少于20个行业实操案例）×1份；', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('⑥ 《考核评估工具包》（含题库、评分表、鉴定模板、评估量表）×1套。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('验收标准：', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('所有课件须适配实际授课场景，经需求方试讲评审通过；实操案例须基于真实旅游业务场景，数据与工具操作步骤经实测可复现；教学大纲须与方案V9版课程表完全对齐；全套交付物须符合政府培训项目档案归档规范。,[PPT设计', ' AI应用开发', ' 教案设计', ' 文案撰写', ' 数据处理],A,48000,2026-05-10,[{name: 教学大纲与课程框架确认', ' deadline: 2026-04-20', ' deliverableDesc: 提交12门课程完整教学大纲及8门核心课件的结构框架（每门课件前5页样稿+目录大纲），经需求方确认后进入全量制作。付款比例：25%（约10', '000元）}', ' {name: 课件与实操手册初稿交付', ' deadline: 2026-04-30', ' deliverableDesc: 提交8套完整授课PPT课件、讲师授课指南及实操训练手册初稿。付款比例：40%（约17', '000元）}', ' {name: 全套终稿与考核工具包交付', ' deadline: 2026-05-10', ' deliverableDesc: 根据反馈修订全部课件终稿，提交案例库及考核评估工具包，完成全套交付物验收。付款比例：35%（约15', '000元）}],open,published,f,2026-04-10 18:00:00,13,[],2026-03-30 07:35:06.483154,2026-03-31 10:39:55.917,[{url: /api/storage/objects/uploads/c302a95a-2ffd-4f0d-85dc-6e97b58f4077', ' name: 关于加强湖南省旅游数智人才队伍建设的实施方案v9.pdf', ' size: 395KB', ' type: application/pdf}],', NULL),
  (26, 'JDB-20260330-0004', '绵阳南山中学 AI 创新实验室空间设计师招募', 'other', '本公司现就绵阳南山中学 “未来智源” 人工智能教育生态建设项目中“AI 创新实验室空间设计”进行公开招募，诚邀具备专业能力的合作方承接本项目空间设计全流程服务，具体要求如下：', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('设计定位：紧扣 “旗舰级・未来实验室” 标准，打造专业级、沉浸式、未来感的 AI 教学空间，契合全省硬件环境最硬核、功能最完备的 AI 教学空间建设要求，适配人工智能教育教学、科研实践、赛事孵化等核心场景。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('核心设计要求', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('（1）功能分区：严格规划四大功能区，AI 教学实训区需支持灵活桌椅布局，实现小组合作探究与大班授课模式切换；科创竞赛孵化区需适配专业操作台、工具墙及 3D 打印机、激光切割机等智造工具摆放；沉浸式体验区需契合 VR/AR 设备、全息投影等交互环境搭建；成果展示与文化长廊需规划数字化成果墙、AI 发展史文化墙及学生作品展示空间。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('（2）专项改造：包含专业声光电改造设计，光环境需适配护眼智能灯光系统，支持按教学场景调节色温与亮度；声学处理需满足小组讨论无干扰、全向拾音及远程同步课堂需求；网络与强电区域需适配万兆光纤、Wi-Fi6 全覆盖及高功率算力设备的安全运行要求。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('（3）软硬件融合：结合实验室硬件集群配置（算力终端、私有云服务器、智阅一体机、AI 视觉机械臂等）进行空间规划，确保软硬件布局深度耦合，兼顾教学、实践、展示、教研多重使用需求。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('服务方资质要求：合作方需提供从空间设计方案构思、效果图输出、施工图绘制，到施工配合、后期优化的全流程服务，确保设计方案落地性强、符合项目实际建设需求。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('合作方资质：需具备独立法人资格，拥有室内空间设计、教育 / 实验室类空间设计相关行业资质，具备科创空间、教育实验室设计成功案例者优先。,[PPT设计', ' 图文设计', ' 品牌策划],A,200000,2026-05-31,[{name: 方案初稿确认\\t', ' deadline: 2026-05-05T00:00:00.000Z', ' deliverableDesc: 提交 AI 创新实验室空间设计方案初稿，含整体布局规划、功能分区设计、声光电改造初步构想，提供 PDF 版方案文本及简易效果图}', ' {name: 方案终稿定稿', ' deadline: 2026-05-10T00:00:00.000Z', ' deliverableDesc: 根据甲方及校方意见修改后，提交设计方案终稿，含全套设计说明、平面布局图、功能分区详图、声光电改造设计图、高清效果图}', ' {name: 施工图纸交付', ' deadline: 2026-05-20T00:00:00.000Z', ' deliverableDesc: 提交全套可落地施工图纸，含平面布置图、立面图、剖面图、节点详图、材料标注等，提供 CAD 版及 PDF 版图纸}', ' {name: 最终成果交付', ' deadline: 2026-05-31T00:00:00.000Z', ' deliverableDesc: 提交设计全流程成果资料汇编（含方案、效果图、施工图、设计交底说明等），完成设计交底，配合甲方完成施工前期对接}],open,published,t,2026-04-15 18:00:00,12,[],2026-03-30 07:42:58.958867,2026-03-31 09:50:20.502,[],', NULL, NULL, NULL, NULL, NULL, NULL),
