  ('【验收标准】：文案需准确传递文旅项目特色且无知识性错误，内容发布后 24 小时内单平台互动量达标，账号月度粉丝增长完成约定指标。,[文案撰写', ' 视频剪辑', ' 图文设计', ' 品牌策划],B,20000,2026-05-31,[{name: 运营方案', ' deadline: 2026-04-15T00:00:00.000Z', ' deliverableDesc: PPT、word}', ' {name: 平台搭建', ' deadline: 2026-04-20T00:00:00.000Z', ' deliverableDesc: 平台链接}', ' {name: 账号运营', ' deadline: 2026-04-25T00:00:00.000Z', ' deliverableDesc: 源文件与发布链接}],open,pending_review,f,2026-04-30 00:00:00,19,[],2026-03-30 13:11:34.855271,2026-03-31 12:38:23.169,[],', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (34, 'JDB-20260330-0012', '人力资源管理系统', 'ai_tool_dev', '一、 系统概述', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('本系统旨在为集团人力资源部门提供数字化的管理工具，目前一期规划主要包含三大核心模块：数据看板、人员信息管理以及薪酬制作及统计 。系统需支持多层级企业架构（涵盖海创元人工智能教育科技、海鑫科技等），实现集团汇总管控与各分公司独立运营的平衡。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('二、 账号与数据权限架构（核心要求）', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('系统必须具备严格的多租户级数据隔离与汇总能力：', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('•	分公司账号：每个子公司需分配独立的系统账号，且各个账号只能查看和管理本公司的数据，做到绝对隔离 。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('•	母公司（集团本部）账号：母企业需设立两个不同权限的账号（账号A与账号B） ：', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('o	集团本部业务账号（账号B）：该账号仅用于管理和查看集团本部自身的人力数据，与其他子公司平级 。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('o	集团全局汇总账号（账号A）：该账号作为最高权限的汇总看板，只负责汇总“母企业B + 所有子企业”的全局数据 。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('三、 核心功能模块需求', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('3.1 数据看板与统计模块', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('该模块需直观展示集团及各分公司的核心人力与经营指标，支持多维度查询：', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('•	多维度查询：系统必须支持随时查询不同时间节点、不同子公司的实时或历史数据 。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('•	关键指标展示：看板需包含以下固定数据指标：人员总数、入职率、离职率 。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('•	人效及财务指标计算：系统需直观展示劳动生产总值、劳动生产率；利润总额、人工成本总额、人工成本利润率；营业总收入、人事费用率、营业总成本、人工成本占总成本费用比重；以及所有者权益 。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('•	数据录入与汇总：各分公司通过系统各自手动录入本企业的经营与人员基础数据 ；汇总账号则展示集团整体数据的自动计算与汇总结果 。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('3.2 人员信息与变动管理模块', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('提供完整的员工生命周期记录与统计：', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('•	员工花名册：按预设的字段（如姓名、用工类型、职级、司龄等）管理人员基础信息 。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('•	人员变动追踪：清晰记录每月的人员动态（例如：“本月新增 3 个”），支持点击下钻查看变动人员的详细信息以及具体的增减原因（如：国投体系外招聘、主动离职等） 。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('•	人数统计逻辑：系统需自动核算并展示净增人数与净减人数 。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('•	分类统计功能：支持用户在系统内筛选特定公司，对该公司的具体人员数据进行分别统计与导出 。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('3.3 薪酬制作与报表模块', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('满足各企业薪资结构的差异化，同时统一集团报税与核算标准：', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('•	独立制表与自定义：每个子企业在系统内分别制作自己的工资表，除固定项外，具体薪资构成内容允许各公司自行编辑 。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('•	六大固定列与算税逻辑：工资表内必须强制包含**“税前薪资合计”、“税前扣款合计”、“个税”、“税后扣款”、“税后补发”、“实发工资”**这6项固定列 。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('•	内置公式：工资表内需预设计算公式，特别要求系统必须能够根据政策自行计算个人所得税 。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('•	导入导出闭环：薪资模块需支持下载/导出空白工资表模板，同时也支持在系统内填报完成后导出最终数据表 。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('3.4 系统全局基础功能', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('•	数据导入：针对历年沉淀的人力资料，系统必须开发历史数据一键导入功能（支持 .xlsx', ' .csv 等格式） 。,[AI应用开发', ' 小程序开发],A,40000,2026-05-24,[{name: 需求分析与方案设计', ' deadline: 2026-04-26T00:00:00.000Z', ' deliverableDesc: "}', ' {name: 平台首页+基础功能', ' deadline: 2026-05-15T00:00:00.000Z', ' deliverableDesc: "}', ' {name: 平台1.0版交付', ' deadline: 2026-05-24T00:00:00.000Z', ' deliverableDesc: "}],open,published,f,2026-04-10 00:00:00,24,[],2026-03-30 08:52:12.458255,2026-03-31 09:40:41.815,[{url: /api/storage/objects/uploads/0e108475-caa0-47da-bc30-0b55d5fc4dc5', ' name: hr_system_prototype.html', ' size: 47KB', ' type: text/html}', ' {url: /api/storage/objects/uploads/6f97a270-5efa-46fb-8663-2d97e06d02a6', ' name: HR系统需求.docx', ' size: 15KB', ' type: application/vnd.openxmlformats-officedocument.wordprocessingml.document}],', NULL, NULL);
INSERT INTO demands (id, demand_no, title, type, description, skill_tags, opc_level, budget, deadline, milestones, mode, status, is_urgent, bid_deadline, publisher_id, directed_opc_ids, created_at, updated_at, attachments, rejection_reason) VALUES
  (33, 'JDB-20260330-0011', '党建AI智能平台开发', 'party_building', '一、 项目概述 本项目旨在开发一款面向各级党政机关、国有企业、非公企业党组织的“党建AI智能平台” 。平台需采用“AI交互”与“综合管理”双轮驱动架构 ，深度融入党务全流程，将党务工作提升为业务驱动的生产力工具 。核心目标是实现“90秒出报告”、“零幻觉输出”以及“全流程闭环” 。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('二、 核心功能模块需求', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('模块A：AI交互端（智能化生成与核查）', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('1.权威党建知识库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('o	需要预置完全符合国家政策的官方权威知识库 。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('o	支持企业或支部建立独立的私域知识库 。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('o	关键技术要求：必须采用“限定知识库”模式，确保输出内容源于权威文件，有效避免AI幻觉（零幻觉） 。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('2.政治合规智能体检', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('o	支持对总结、学习心得、思想汇报等文档进行全文扫描与实时检测 。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('o	具备智能识别敏感词与不当表述的能力 。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('o	能够针对检测出的问题提供修改建议，确保文稿严谨合规 。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('3.活动策划方案生成', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('o	用户输入活动主题、参与人数等基础信息后，能够一键快速生成策划方案 。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('o	方案内容需覆盖活动目的、流程安排、人员分工等模块 。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('o	场景适配：需适用于主题党日、三会一课、党员教育培训等场景 。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('4.党建助手辅助创作', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('o	提供大纲生成、素材推荐与内容润色功能，减轻起草负担 。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('o	辅助撰写“三会一课”记录、会议摘要、宣讲提纲等 。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('o	支持基于会议录音，快速生成规范的文稿框架 。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('5.智能PPT生成', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('o	用户输入文本大纲，系统可一键生成排版精美、符合党建专业风格的PPT 。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('o	支持将生成的PPT导出为PPT或PDF格式 。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('模块B：综合管理端（数字化党务管理）', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('1.党员档案与党费管理', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('o	实现党员信息的数字化精准维护 。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('o	支持入党全流程的进度追踪 。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('o	具备智能计算党费标准的功能，并能实现自动催缴提醒（自动化、透明化） 。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('2.数据可视化', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('o	开发数据大屏，实时展示党建相关数据 。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('3.自动化报告生成', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('o	通过AI工作流，自动完成并生成月度统计报告，实现提效 。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('模块C：非公党建专项能力（深层治理与产业服务）', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('1.“一企一户”实时画像：支持自动巡检公开网络信息，无需人工“扫楼”即可掌握辖区企业最新的融资、人才、业务动态 。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('2.精准投喂：根据企业真实需求（如人才落户、产业链对接等）进行快速筛选匹配，实现精准产业服务与政策投喂 。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('3.“大手拉小手”机制：在系统中建立大企业带动小企业的联动模式，通过业务交流吸引非公企业参与党建活动 。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('三、 系统集成与技术要求', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('1.全流程闭环：平台功能需完整覆盖从文稿起草到党员管理的党建全场景 。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('2.账号与集成：系统需支持SSO统一登录，并能够与企业微信实现无缝集成 。,[AI应用开发', ' 小程序开发],A,59800,2026-04-30,[{name: 需求分析与方案设计', ' deadline: 2026-04-12T00:00:00.000Z', ' deliverableDesc: "}', ' {name: 平台首页+基础功能', ' deadline: 2026-04-24T00:00:00.000Z', ' deliverableDesc: "}', ' {name: 平台1.0版交付', ' deadline: 2026-04-30T00:00:00.000Z', ' deliverableDesc: "}],open,published,f,2026-04-05 00:00:00,24,[],2026-03-30 08:38:29.426188,2026-03-31 09:41:08.276,[{url: /api/storage/objects/uploads/8c921a23-9fe1-415a-a58a-38fbc863e923', ' name: 党建AI智能平台1.jpg', ' size: 820KB', ' type: image/jpeg}],', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (31, 'JDB-20260330-0009', '初中阶段无编程基础的科普课程开发', 'ai_education', '课程定位： 针对无编程基础的青少年（初中阶段），开发通识性、趣味性强的人工智能科普课程。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('内容规划： 课程设计需包含AI技术发展史、基础概念科普以及前沿科技感知（如VR/AR体验或机器人简单演示）等模块。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('交付标准： 需交付一套完整的标准化授课包，包含课程大纲、教师授课课件（PPT）、简易教案及配套体验活动的指导手册。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('应用场景： 该套课程主要用于周末科普开放日、周边学校来访的短期研学体验，以及校内常规的科技节宣讲活动 。,[PPT设计', ' AI应用开发', ' 图文设计', ' 提示词工程],B,20000,2026-04-15,[],open,closed,f,2026-04-08 12:00:00,17,[],2026-03-30 08:10:23.850679,2026-03-30 09:15:01.842,[],', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (30, 'JDB-20260330-0008', '企业融资额度测算工具开发服务', 'ai_tool_dev', '1、开发定制化企业融资额度测算应用程序（APP/小程序） ；', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('2、核心功能需实现：企业用户上传财务报表、资质证明等材料后，系统基于AI算法智能测算可申请融资额度 ；', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('3、需提供多维度企业财务健康评估报告 ；', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('4、需支持多类融资产品的额度匹配与推荐 ；', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('5、承接方需负责需求对接、功能设计、技术开发及上线前的测试调试，并提供三个月的基础售后技术支持（含Bug修复、性能优化等）。,[AI应用开发', ' Vibe Coding', ' 数据处理', ' 小程序开发', ' Python编程', ' 图文设计],A,100000,2026-06-30,[{name: 需求对接与功能设计确认', ' deadline: 2026-05-08T00:00:00.000Z', ' deliverableDesc: 形成双方确认的需求文档}', ' {name: 技术开发与上线前测试调试', ' deadline: 2026-05-30T00:00:00.000Z', ' deliverableDesc: 开发小程序上线}', ' {name: 交付上线及三个月基础售后技术支持', ' deadline: 2026-06-30T00:00:00.000Z', ' deliverableDesc: 小程序正式上线运行，并伴随后续三个月售后技术支持}],open,published,f,2026-04-30 00:00:00,14,[],2026-03-30 08:10:18.527667,2026-03-31 09:41:58.638,[],', NULL, NULL, NULL, NULL, NULL, NULL),
  (37, 'JDB-20260413-0001', 'AI技术讲师招募 - 全栈开发与教学能力（政企方向培训）', 'gov_training', '【技术要求】', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
