  (36, 'JDB-20260331-0001', '初中阶段无编程基础的科普课程开发', 'ai_education', '课程定位：针对无编程基础的青少年（初中阶段），开发通识性、趣味性强的人工智能科普课程。内容规划：课程设计需包含AI技术发展史、基础概念科普以及前沿科技感知（如VR/AR体验或机器人简单演示）等模块。交付标准：需交付一套完整的标准化授课包，包含课程大纲、教师授课课件（PPT）、简易教案及配套体验活动的指导手册。应用场景：该套课程主要用于周末科普开放日、周边学校来访的短期研学体验，以及校内常规的科技节宣讲活动。', '["PPT设计", "AI应用开发", "图文设计"]', 'A', 100000, '2026-04-15', '[]', 'open', 'published', 'f', '2026-04-08 12:00:00', 17, '[]', '2026-03-31 09:39:22.669277', '2026-03-31 09:39:23.095', '[{"url": "/api/storage/objects/uploads/fbbc4774-b946-44b4-a990-5886561d62e8", "name": "AI科普课程定制开发需求说明书.pdf", "size": "139KB", "type": "application/pdf"}, {"url": "/api/storage/objects/uploads/3aa0e1f8-03d2-4b18-9b18-27874fd48bbe", "name": "学校介绍.pdf", "size": "54KB", "type": "application/pdf"}]', NULL),
  (32, 'JDB-20260330-0010', '直播/新媒体获客运营服务', 'livestream_media', '1、寻求专业的直播/新媒体运营团队，提供全流程运营支持 ；', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('2、包含制定符合业务定位的新媒体运营策略（须确保内容合规，符合《广告法》等法规要求） ；', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('3、包含直播脚本策划、公众号/短视频内容制作 ；', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('4、包含线索筛选、客户意向分级与导流 。,[视频剪辑', ' 文案撰写', ' 直播运营', ' 短视频制作', ' 图文设计', ' 品牌策划],A,200000,2026-07-30,[{name: 运营方案及策略制定', ' deadline: 2026-05-30T00:00:00.000Z', ' deliverableDesc: 运营方案及策略方案提交}', ' {name: 内容制作与账号日常运营', ' deadline: 2026-06-30T00:00:00.000Z', ' deliverableDesc: "}', ' {name: 索导流与按月度结算分润', ' deadline: 2026-07-30T00:00:00.000Z', ' deliverableDesc: "}],open,published,f,2026-04-30 00:00:00,14,[],2026-03-30 08:17:21.177718,2026-03-31 09:42:14.791,[],', NULL, NULL, NULL, NULL, NULL, NULL),
  (40, 'JDB-20260416-0001', '智慧校园多系统数据整合与学生成长画像开发项目招募', 'ai_tool_dev', '一、 项目背景与任务要求', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('本项目旨在解决当前校园内十余个信息化系统之间的数据孤岛问题。通过底层数据抽取与清洗，以学生为核心建立统一的数据资源库，并最终形成可视化的学生成长轨迹，为校方的教育教学与管理提供有效的数据支撑。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('任务要求：', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('数据准确性： 必须以“学生学号”为核心主键（“姓名+班级”为辅键）进行多表精准关联，妥善处理重名、缺失值及脏数据，确保同一名学生的跨系统数据能够准确归集。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('数据安全性： 严格遵守校园数据隐私及安全管理规范，开发与测试期间需进行数据脱敏处理，严禁任何形式的数据外泄。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('流程自动化： 需设计稳定可靠的ETL（数据提取、转换、加载）流转机制，支持数据的定期更新与自动同步，降低后续人工运维成本。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('架构扩展性： 总表及底层数据资源库的设计需具备良好的扩展性，以便未来无缝接入更多校内新增的信息化业务系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('二、 工作内容', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('系统调研与接口梳理： 对校内现有的十余个信息化系统（如教务、图书管理、一卡通、综合素质评价等）进行底层数据库或API接口的调研，明确各系统的数据字典与字段映射关系。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('数据抓取与清洗合并： 开发数据抽取脚本或中间件，将各系统中的散乱数据提取出来，统一数据格式与标准，汇聚至中心库的总表中。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('成长轨迹逻辑构建与开发： 紧密结合校方业务需求，提取核心数据指标（如学业波动、考勤纪律、阅读偏好、活动参与等），开发“学生成长轨迹”生成引擎。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('前端展示与导出功能： 开发相应的可视化界面（推荐采用简洁明朗的蓝白清爽视觉风格，避免界面过于繁杂暗沉），支持校方按不同维度查看轨迹，并支持一键导出标准化的成长报告。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('三、 交付物规格', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('《多系统数据集成与字段映射说明书》： 包含各系统数据源清单、数据清洗规则及总表数据结构说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('源代码与部署包： 包含所有数据抽取、清洗脚本及成长轨迹生成模块的完整源代码，代码需包含规范的中文注释。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('统一数据资源库（总表）： 部署完成并结构化良好的中心数据库，包含首批全量清洗完毕的历史数据。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('《系统部署与操作指导手册》： 包含环境搭建说明、定时任务配置规则及系统日常维护的标准操作流程（SOP）。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('四、 验收标准', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('功能完整性： 成功对接所有清单内的信息化系统，数据流转链路通畅，成长轨迹模块功能与校方原始需求完全一致。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('数据质量达标： 随机抽样100名学生进行跨系统数据核对，数据关联准确率需达到 99% 以上，且各系统维度数据无张冠李戴现象。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('系统稳定性： 增量数据同步任务运行平稳，无内存泄漏或进程异常中止现象；前端页面响应迅速、运行流畅。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('交付物规范： 交付的文档资料齐全、格式标准，源代码符合通用开发规范，顺利通过我方技术团队的代码审查与系统联调测试。,[数据处理', ' Web开发', ' AI应用开发],A,40001,2026-05-31,[{name: 需求分析和方案设计', ' deadline: 2026-05-01', ' deliverableDesc: "}', ' {name: 系统功能初交付', ' deadline: 2026-05-15', ' deliverableDesc: "}', ' {name: 需求调整和产品优化', ' deadline: 2026-05-22', ' deliverableDesc: "}', ' {name: 项目验收', ' deadline: 2026-05-30', ' deliverableDesc: "}],open,published,t,2026-04-30 17:33:00,1,[],2026-04-16 09:35:54.182383,2026-04-16 09:42:42.537,[],', NULL, NULL, NULL, NULL, NULL, NULL),
  (38, 'JDB-20260414-0001', 'AI培训', 'gov_training', '对企业进行AI培训', '["教案设计"]', 'any', 30000, '2026-05-30', '[]', 'open', 'closed', 't', '2026-04-24 09:44:00', 1101, '[]', '2026-04-14 01:45:11.596185', '2026-04-14 01:45:12.007', '[]', NULL),
  (39, 'JDB-20260414-0002', '高校教师教学竞赛AI辅助', 'ai_tool_dev', '开发一个高校教师竞赛智能辅助系统', '["AI应用开发"]', 'any', 50000, '2026-05-30', '[]', 'open', 'draft', 'f', '2026-04-14 00:00:00', 1129, '[]', '2026-04-14 06:50:05.924193', '2026-04-15 10:48:10.966', '[]', '请补充更详细的需求，可以通过和大模型的沟通输出平台需求，例如：系统核心功能说明'),
  ('基于对高校教师教学竞赛管理现状的调研，本系统在常规管理功能基础上，重点强化了以下智能化模块：', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
