  ('完成 采集-上架-AI修改链接-转化语言，标题-完成产品上架发布', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('如果做过这种业务的可以，很简单，就是影刀的指令应用,[AI应用开发],any,1000,2026-04-30,[],open,pending_payment,f,2026-04-30 10:20:00,1292,[],2026-04-20 01:16:35.105758,2026-04-20 01:16:35.652,[],', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (41, 'JDB-20260417-0001', 'AI电商自动化', 'other', '用AI赋能电商行业 有单子 找技术长期合作', '["AI应用开发", "提示词工程", "直播运营", "短视频制作", "数据处理", "Python编程", "小程序开发"]', 'any', 1000, '2026-04-30', '[]', 'open', 'pending_payment', 't', '2026-04-17 13:16:00', 1231, '[]', '2026-04-17 05:24:25.801234', '2026-04-17 05:24:26.327', '[]', NULL),
  (44, 'JDB-20260422-0001', '面向企业的绩效核验系统本地化建设项目需求', 'ai_tool_dev', '本项目是面向企业的绩效奖励核算与复核场景，拟建设一套可在内网环境部署运行的绩效核验系统。系统需围绕当前绩效核算过程中存在的人工复算效率低、规则执行一致性差、季度政策调整频繁、异常数据识别依赖人工经验等核心问题，建立“业务部门填报、人力部门核验、系统自动比对、异常结果预警”的标准化处理机制。结合会议沟通内容与现场记录，系统建设的核心目标是通过规则引擎、自动计算、异常识别与低代码维护能力，提升绩效核算效率、降低人工核验成本，并确保奖金发放依据与最新奖励办法保持一致。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('         当前业务流程中，绩效奖励通常由多个业务管理部门发起，涉及约 30 余个部门、300—400 名相关人员参与流转。业务部门负责提供业绩基数、填报奖励结果或相关基础数据，人力部门不负责业务真实性核验，主要承担对计算逻辑与奖励办法一致性的复核责任。由于现阶段业务端往往仅提交最终结果而不提交完整计算逻辑，人力部门需要依据当期奖励政策进行逐条复算，既增加了工作量，也带来了错用系数、沿用旧版规则、遗漏上下限约束等风险。因此，本项目的任务内容不仅是开发一个录入与展示系统，更重要的是建设一套可持续运转的绩效规则核验能力平台。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('         系统交付范围应覆盖需求分析、原型设计、规则梳理、系统开发、测试验证、部署实施、试运行支持、规则调优与交付培训等完整建设内容。技术方案上，需优先适配客户现有本地模型与 API 能力基础，包括但不限于 DeepSeek、通义千问、MiniMax、GLM 等能力环境，但具体是否引入大模型以及引入深度，应以本地安全可控、规则可解释、结果可审计为前提。系统设计应坚持“规则引擎为主、模型能力为辅”的原则，避免形成黑盒式核算结果。,[Vibe Coding', ' AI应用开发', ' 数据处理],any,30000,2026-07-31,[{name: 完成项目启动、边界确认与资料收集，形成正式需求输入', ' deadline: 2026-05-30T00:00:00.000Z', ' deliverableDesc: 交付《项目启动纪要》1 份、《需求调研问题清单》1 份、《资料收集清单》1 份。客户需同步提供脱敏后的绩效样本、现行及历史政策文件、当前流程说明、角色名单及环境约束说明。}', ' {name: 梳理绩效核算逻辑并完成原型验证设计', ' deadline: 2026-06-15T00:00:00.000Z', ' deliverableDesc: 交付《业务流程与角色说明》1 份、《绩效规则梳理清单》1 份、《原型设计稿》1 套、《原型验证方案》1 份。需覆盖典型规则、复杂规则、异常场景与配置方式说明。}', ' {name: 基于脱敏数据验证规则匹配度与计算可行性，确认正式开发范围', ' deadline: 2026-06-25T00:00:00.000Z', ' deliverableDesc: 交付《原型验证报告》1 份、《样本测算对比结果》1 份、《需求确认清单》1 份、《正式建设范围说明》1 份。该节点需确认哪些规则已跑通、哪些边界场景需在正式阶段处理。}', ' {name: 完成核心系统开发、规则引擎建设、权限与流程联调', ' deadline: 2026-06-30T00:00:00.000Z', ' deliverableDesc: 交付可运行测试版本 1 套、《系统功能说明书》1 份、《接口与数据字典》1 份、《测试案例与测试报告》1 份。系统应覆盖规则配置、数据导入、自动核验、异常预警、结果查询等核心功能}', ' {name: 在客户本地环境部署上线，并通过陪跑提升稳定性与规则适配度', ' deadline: 2026-07-10T00:00:00.000Z', ' deliverableDesc: 交付正式部署版本 1 套、《部署实施文档》1 份、《运维手册》1 份、《试运行问题台账》1 份、《阶段优化报告》1 份。试运行周期建议 2—3 个月。}', ' {name: 完成最终验收、培训与后续维护机制确认', ' deadline: 2026-07-31T00:00:00.000Z', ' deliverableDesc: 交付《项目验收报告》1 份、《用户操作手册》1 份、《管理员配置手册》1 份、《培训材料》1 份、《后续维护与陪跑建议》1 份。该节点标志客户可在后续周期中独立维护常规规则。}],open,published,f,2026-05-20 00:00:00,1,[],2026-04-22 02:13:30.150531,2026-04-24 06:06:40.029,[],'),
