  (527, 567, 'newbie', '《意游记》教育心理构建项目 · 案例展示', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('项目名称', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('《意游记》—— 八十一境心灵成长课程体系', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('项目类型', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('教育心理构建 / 企业文化培训 / 青少年心灵成长课程', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('项目简介', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('《意游记》是一部以“字灵儿”为主角的现代心灵寓言，讲述五个少年（道元、易阳、空明、财济、人诚）从仙湖出发，历经八十一境，最终回归本心的成长故事。每一境对应一个心理成长主题：自我认知、情绪管理、人际关系、价值创造、生命意义等。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('本项目将《意游记》开发为一套可落地的心理构建工具包，适用于学校心理健康教育、企业文化建设、团队凝聚力培训、青少年营地教育等场景。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('项目背景', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('当前教育体系普遍重知识轻心智，职场人面临焦虑与迷茫，青少年缺乏自我认知的路径。《意游记》以故事为载体，以“字灵儿”为角色原型，将东方哲学（道德经、易经、金刚经、范蠡商道）转化为通俗易懂的心灵成长模型。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('我的贡献', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('作为项目主创，我完成了以下工作：', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('内容体系构建：设计八十一境完整叙事框架，提炼九个心理成长阶段（意、志、探、趣、智、戏、具、悦、境）。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('角色心理学模型：将道元（方向感）、易阳（适应性）、空明（情绪觉察）、财济（价值分享）、人诚（自我记录）转化为可教学的人格特质模型。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
