INSERT INTO posts (id, author_id, title, content, tags, likes_count, comments_count, views_count, created_at, updated_at, is_featured) VALUES
  (4, 1, '大家都想接到什么样的订单？', '留言告诉我们，什么样的订单你最喜欢，包括喜欢的原因等，我们为大家去争取更多订单。', '{#接单经验,#问卷调查}', 2, 7, 0, '2026-03-30 16:52:32.506632', '2026-03-30 16:52:32.506632', 'f'),
  (8, 19, 'AI + 新媒体：如何用智能工具重构运营全链路，实现降本增效', '以前做运营，选题、写稿、做图、剪视频、复盘，一天下来累到崩溃，还总赶不上进度。但在 AI 时代，这些问题真的能迎刃而解！今天就给大家唠唠，我是怎么用 AI 把新媒体运营效率拉满的👇', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('1. 内容创作：再也不用熬夜写稿了', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('以前写一篇小红书笔记，光想选题、凑文案就要大半天。现在直接把需求丢给 AI：“帮我写一篇适合宝妈群体的 AI 育儿工具种草笔记，标题要抓眼球，内容要接地气，带 3 个话题标签”，分分钟就能出初稿，我只需要稍微润色、加一点个人真实体验，一篇笔记就搞定了，效率直接翻 10 倍！不管是公众号、抖音口播、朋友圈文案，AI 都能一键生成，还能帮你适配不同平台的风格，再也不用为写东西头疼了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('2. 做图剪视频：不用求设计师、不用学剪辑', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('以前做个封面、海报，要么自己用 PS 抠半天，要么花钱找设计师，又慢又贵。现在用 AI 绘图工具，输入关键词就能生成高质量配图，用 AI 设计工具一键排版，几分钟就能出一张专业海报。剪视频更爽！AI 能帮你写脚本、做数字人出镜、自动剪辑、加字幕、配 BGM，以前剪一条视频要一下午，现在半小时就能搞定，个人也能轻松做账号，再也不用被剪辑软件劝退了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('3. 复盘运营：用 AI 帮你做决策，少走弯路', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('以前做数据复盘，要自己去各个平台导数据、做表格、分析，费时间还容易出错。现在用 AI 工具，自动帮你抓取数据、生成报表，还能分析你的爆款内容逻辑、用户喜好，帮你调整运营方向，再也不用靠感觉做决策了。就连竞品分析，AI 都能帮你批量扒竞品账号的内容、数据，快速出分析报告，让你一眼看懂行业趋势，找准自己的赛道。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('4. 最后说句实在话', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('AI 真的是运营人的 “外挂”，但它只是工具，不能完全替代我们。内容的温度、品牌的调性、和用户的情感连接，还是要靠我们自己来把控。用 AI 把重复的活干了，我们才能把时间花在更有价值的创意、用户沟通上，真正实现降本增效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('评论区聊聊你们的宝藏 AI 工具和提效小技巧，一起交流学习！,{#新手攻略', '#AIPrompting},2,0,0,2026-03-31 09:39:04.607336,2026-03-31 09:39:04.607336,t', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (7, 14, '立信华辉业务快速发展，亟需采购各项服务，快来接单吧！', '立信华晖（北京）企业管理有限公司在企业管理咨询、数字化工具开发、新媒体营销、AI技术应用等领域有业务需求，希望有能力的OPC企业为我司业务拓展与运营效率提升提供全流程服务支持。', '{#VibeCoding,#政企数字化}', 2, 0, 0, '2026-03-31 09:36:39.25077', '2026-03-31 09:36:39.25077', 't'),
  (2, 9, '政企数字化转型中的大模型合规边界探讨', '在一次国家政务项目中，我们遭遇了模型输出合规性的严峻挑战。整理了几条实战经验，关于敏感词过滤、数据脱敏流程以及审计日志的最佳实践…', '{#合规,#政企数字化,#大模型}', 621, 31, 1800, '2026-03-25 06:27:33.231871', '2026-03-25 06:27:33.231871', 'f'),
  (1, 9, '关于 #VibeCoding 在工业级项目中的实际落地探讨', '最近在处理一个复杂的LLM集成项目，我们尝试引入了VibeCoding的概念。不仅提高了Prompt的容错率，还显著降低了上下文窗口的损耗。这里分享一些心得…', '{#VibeCoding,#AIPrompting,#TechTalk}', 1241, 86, 4500, '2026-03-25 06:27:33.228009', '2026-03-25 06:27:33.228009', 'f'),
  (3, 9, '新手OPC如何快速获得第一单？我的三个月复盘', '三个月前我刚注册接单吧，什么都不会。现在已经完成了4单，累计结算2.8万。分享一下我踩过的坑和经验总结…', '{#新手攻略,#接单经验,#成长}', 891, 70, 3200, '2026-03-25 06:27:33.235188', '2026-03-25 06:27:33.235188', 'f'),
  (15, 13, '文旅干部AI赋能培训，我们在探路！', '如何让文旅系统干部真正"用起来"人工智能，而不是"听过就忘"？', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('学院正式启动文旅干部AI素养提升计划！我们聚焦实战，探索场景+课程+实训三位一体培训模式，让AI能力真正落地文旅一线。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('我们的目标：让每一位文旅干部敢用AI、会用AI、善用AI！', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('诚邀在AI教育课程研发、实训平台搭建方面有经验的合作伙伴，共同打造文旅领域AI培训新标杆。,{#接单经验', '#AI教育项目},2,4,0,2026-03-31 10:16:41.394955,2026-03-31 10:16:41.394955,t', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (13, 17, '内蒙古呼伦贝尔的一所中学定制开发AI科普课程的需求已发布', '呼伦贝尔市牙克石第二中学正全力打造“人工智能创新教育示范基地”。为发挥基地的科普辐射作用，现面向行业招募优秀的课程开发者/服务商，为我校量身定制一套AI科普基础课程。期待您的加入，共同助力青少年科学素养提升！', '{#政企数字化,#接单经验}', 2, 1, 0, '2026-03-31 09:51:25.38869', '2026-03-31 09:51:25.38869', 't'),
  (18, 17, '针对无编程基础的青少年，开发人工智能科普课程紧急招募', '服务商需在约定的开发周期内，为校方全量交付课程包。诚邀符合条件的服务商或开发者团队与我们尽快联系洽谈。', '{#合规,#政企数字化}', 3, 3, 0, '2026-03-31 10:30:40.150039', '2026-03-31 10:30:40.150039', 't'),
  (14, 13, '文旅干部AI素养培训课程体系开发合作招募', '中央文化和旅游管理干部学院现面向社区招募AI教育课程开发合作方。项目背景：学院承担文旅系统干部培训及"一带一路"国际援助培训任务，现需将人工智能素养模块融入现有课程体系，提升学员数字化能力。核心需求：围绕文旅场景定制AI通识课程、实操教学内容及配套数字资源包，支持中英文双语交付。欢迎具备AI教育课程研发经验、了解政府培训体系的服务商积极对接！', '{#接单经验,#AI教育项目}', 2, 0, 0, '2026-03-31 10:16:10.459386', '2026-03-31 10:16:10.459386', 't'),
  (11, 12, 'AI 创新实验室空间设计师招募~', '四川省绵阳南山教育投资有限公司现面向社区招募AI 创新实验室空间设计方，具体信息如下：', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('项目定位：打造旗舰级未来 AI 教育实验室，适配教学、科研、竞赛孵化等场景', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('核心要求：完成功能分区设计、声光电改造、软硬件融合布局', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
