  ('交付截止：2026 年 5 月 31 日', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('报名要求：具备独立法人资格及教育 / 实验室空间设计案例，可提供完整设计团队', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('有意向的设计师 / 设计团队可在评论区留言或私信对接，期待与专业伙伴合作！,{#接单经验', '#空间设计 #教育空间设计#实验室设计 #AI 教育项目},3,2,0,2026-03-31 09:42:41.139398,2026-03-31 09:42:41.139398,t', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (19, 25, '从业经验20年的专业OPC', '本人具备大模型应用、政企项目、安全合规、数据治理等20年从业经验，有国企案例经验，技术过硬、服务好，5星满分好评如潮，从业至今无差评。', '{}', 3, 2, 0, '2026-03-31 10:39:18.568901', '2026-03-31 10:39:18.568901', 'f'),
  (10, 24, '招募开发人力资源管理系统', '本系统旨在为集团人力资源部门提供数字化的管理工具，目前一期规划主要包含三大核心模块：数据看板、人员信息管理以及薪酬制作及统计 。系统需支持多层级企业架构，实现集团汇总管控与各分公司独立运营的平衡。', '{#政企数字化}', 4, 3, 0, '2026-03-31 09:42:36.442103', '2026-03-31 09:42:36.442103', 't'),
  (12, 24, '招募开发党建AI智能平台', '项目概述 本项目旨在开发一款面向各级党政机关、国有企业、非公企业党组织的“党建AI智能平台” 。平台需采用“AI交互”与“综合管理”双轮驱动架构 ，深度融入党务全流程，将党务工作提升为业务驱动的生产力工具 。核心目标是实现“90秒出报告”、“零幻觉输出”以及“全流程闭环” 。', '{#政企数字化}', 2, 1, 0, '2026-03-31 09:43:13.307291', '2026-03-31 09:43:13.307291', 't'),
  (17, 15, '诚邀志同道合的您，加入我们~', '让每一位老师都能玩转AI，让每一个孩子都能接轨未来！', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
