  (16, 15, '#AI教育加速跑# 助力数字化转型，我们在行动！', '如何打破中小学AI教育“课程碎、师资缺、资源少”的僵局？', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('海亮教育正式开启AI教育赋能行动！我们聚焦痛点，通过“政策+方案+实操”闭环模式，帮助教师系统掌握教学路径。,{},3,0,0,2026-03-31 10:27:32.606912,2026-03-31 10:27:32.606912,t', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (9, 12, '施工图监理人员合作招募', '绵阳南山中学 AI 创新实验室建设项目，面向社区公开招募施工图监理人员，具体需求如下：', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('一、项目背景', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
