  (22, 303, '用AI协助出版，自有出版发行平台，交流', '用AI工具生产内容，内容可发布在运营成熟平台，通过平台提高出版的水平和扩大朋友圈。', '{#接单经验,#新手攻略}', 0, 1, 0, '2026-04-08 06:58:52.379152', '2026-04-08 06:58:52.379152', 'f'),
  (20, 92, '小程序的定制开发', '大家好，本人多年开发经验，希望能接一些小程序的定制开发项目。只要接下的项目我都会踏踏实实去打磨，保证沟通透明、有始有终，如果您刚好有小程序开发或者系统AI化升级的需求，欢迎随时找我聊聊。', '{#小程序开发}', 3, 1, 0, '2026-04-07 15:43:37.943792', '2026-04-07 15:43:37.943792', 'f'),
  (36, 452, '现阶段OPC路径', '身边普通OPC各种情况：', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('实物产品落地的几乎没有坚持下来的，产品落地某个环节可能就卡住了；', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
