  (23, 369, '现在开始学ai', '使用生成式ai最重要的能力是什么？有大佬可以告诉我吗？', '{#新手攻略}', 0, 2, 0, '2026-04-08 09:04:46.158982', '2026-04-08 09:04:46.158982', 'f'),
  (29, 721, '专业+AI', '规划设计行业已走向下坡路，但二十多年的工作经验不想就此作废，希望AI或者其他新手段能赋予其新生命。', '{#新手攻略,#AIPrompting,#接单经验}', 1, 1, 0, '2026-04-10 07:44:21.116983', '2026-04-10 07:44:21.116983', 'f'),
  (28, 706, 'Hello OPC，Hello AI!', '上个墙！证明我来过。', '{#VibeCoding,#政企数字化,#合规,#接单经验}', 0, 1, 0, '2026-04-10 06:37:42.687749', '2026-04-10 06:37:42.687749', 'f'),
  (34, 1073, '这里有案例，有上架成品，有实力，最重要是好沟通', '也许下一个蓝海就被你碰见了~', '{}', 0, 1, 0, '2026-04-13 11:22:22.37015', '2026-04-13 11:22:22.37015', 'f'),
  (37, 452, 'OPC网站备案', '有一些网站备案，需要资质相对严格，OPC满足不了，希望有天会更加友好。', '{}', 0, 1, 0, '2026-04-15 01:04:43.266183', '2026-04-15 01:04:43.266183', 'f'),
  (24, 452, 'OPC需要IP', 'OPC不想芸芸众生，必须从一开始就树立IP概念。AI工具会越来越强大，OPC门槛会越来越低。不能给人信任感，就不能长久，IP就是唯一出路，OPC需要把自己打造成品牌。品牌的核心就是一个好的名字，正向、易记、容易传播……。必然就需要考虑商标、域名，名正言顺。一个好的名字，也是实力的体现。1999年开始接触互联网，到今天进入AI阶段，经历了中国互利网的好多阶段，依然还在战斗，现在同为OPC，在商标和域名方面，如有需要可以联系我，免费提供建议，也欢迎OPC们交流。', '{#新手攻略}', 2, 1, 0, '2026-04-09 00:49:30.340337', '2026-04-09 00:49:30.340337', 'f'),
  (35, 1150, 'AIGC接单', '关于AI生成内容可以找我，商业广告还是娱乐，还是AI动态慢，Ai短剧，这些我都有合作案例', '{#政企数字化,#合规,#接单经验,#新手攻略,#AIPrompting,#VibeCoding,#AIGC}', 0, 1, 0, '2026-04-14 15:37:31.098564', '2026-04-14 15:37:31.098564', 'f'),
  (33, 1055, '超级外包', '以最低的价格，最快的速度，最专业的技术接单', '{}', 1, 2, 0, '2026-04-13 07:43:28.952795', '2026-04-13 07:43:28.952795', 'f'),
  (32, 1013, '目前主要做小程序开发，软件定制开发及工业视觉识别', '见证一下超级个体能否在这个时代存活', '{}', 0, 1, 0, '2026-04-12 16:21:55.323318', '2026-04-12 16:21:55.323318', 'f'),
  (30, 821, '共创未来', 'OPC 交易平台正式上线，是个体价值与数字生态的双向奔赴。从单打独斗到协同共赢，从技能沉淀到高效变现，平台为一人公司搭建可信桥梁。愿以专业立身，以诚信致远，在新赛道上深耕价值、共创未来。', '{}', 1, 1, 0, '2026-04-10 14:35:14.55813', '2026-04-10 14:35:14.55813', 'f'),
  (38, 1176, 'AI合规咨询：算法备案、大模型备案、大模型登记', '已助力500+企业履行算法、大模型备案/登记手续，备案+各地大模型补贴政策，提供免费咨询服务', '{#算法备案,#大模型备案,#大模型登记,#AI合规,#深度合成服务}', 2, 0, 0, '2026-04-15 10:12:29.837124', '2026-04-15 10:12:29.837124', 'f'),
  (39, 23, '诚邀参加 | OPC国际枢纽站·一人公司线下见面会', '在人工智能与数字化办公飞速发展的当下，我们深知每一位 OPC（One-Person Company）创作者都在探索更高效的商业模式与更广阔的发展空间。', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
