INSERT INTO publisher_profiles (user_id, company_desc, location, industry, team_size, founded_year, website, contact_email, updated_at, credit_code, company_logo) VALUES
  (11, '海创元 X 原点社区OPC 联合运营体', '北京市', '政府OPC', '1-10人', 2026, 'www.opcorder.com', 'sales@aieducenter.com', '2026-03-31 12:10:56.99', NULL, '/api/storage/objects/uploads/128e5964-8081-4922-a172-f8edb9761354'),
  (1, '北京海创元人工智能教育科技有限公司是海淀国投集团全资企业，专注于AI教育全链赋能生态服务。公司业务涵盖“智教服务集群+产融生态矩阵”八大业务线，形成双轮驱动发展体系，致力于为学校、政企、OPC个体及合作伙伴提供一站式AI教育解决方案。', '北京市', 'AI教育', '11-50人', 2025, 'www.aieducenter.com', 'support@aieducenter.com', '2026-03-30 16:46:48.763', '91110108MA01WL8HXY', '/api/storage/objects/uploads/1e582619-2a69-434f-824f-e671eb092052'),
  (17, '        牙克石第二中学始建于2012年，位于牙克石市通河东街北，是标准化初级中学，学制三年。2012年牙克石市委、市政府整合市二中、市三中、市六中优质教育资源，筹建自治区级标准化初级中学命名为牙克石市育才中学，2014年搬入新校区，2019年4月重新更名为牙克石市第二中学。学校占地面积12万平方米，现有教学综合楼、实验楼、学生宿舍楼、报告厅、生活服务中心、足球馆6个单体建筑，总建筑面积45980平方米。学校运动场16966平方米；学校校园布局合理，环境优美，设施配套，功能完善。现有33个教学班,在编教职工257人，专任教师数203人，其中副高级职称115人，中级职称65人，初级23人，教辅人员47人，7名工勤。学生约1500人。配有图书室、实验室、美术教室、录播教室、书法教室、创客空间、心灵驿站等33个功能教室。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('先后获得牙克石市先进集体、牙克石市先进基层党总支、呼伦贝尔市文明校园、呼伦贝尔市文明单位、自治区德育示范校、依法治校示范校、呼伦贝尔市优秀基层党组织、呼伦贝尔市传统项目学校、全区民族团结教育先进单位、“国家级写字实验校”、国家级足球特色学校、国家级校园冰雪运动特色学校等荣誉称号。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('         学校始终坚持“办为林区人民负责任的学校”的办学指导思想，秉承“天道酬勤、厚德载物”的发展精神，坚持“依法治校，以德立校，科研兴校，质量强校”的办学目标。进一步提高管理水平，优化教育教学环境，强化师资队伍建设，走内涵式发展之路，在教科局的正确领导下，坚持科学管理，求真务实，扎实工作，让各项工作稳步前行。,内蒙古自治区呼伦贝尔市,教育,201-500人,2012,,1157374867@qq.com,2026-03-31 09:49:09.375,12152104065025583Q,/api/storage/objects/uploads/f73a9094-53b3-44f5-b1cc-68ebac335d75', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (12, '四川省绵阳南山教育投资有限公司专注于教育投资与房地产开发领域。公司核心业务包括教育咨询管理、教育模式输出及教育实业投资，同时从事房地产开发经营。通过与地方教育机构合作，公司参与了绵阳中学资阳育才学校等教育项目的建设与运营，该校为12年一贯制学校，覆盖小学至高中教育阶段。公司业务模式整合教育投资与地产开发，形成协同效应，有效支持区域教育产业的扩展需求。在项目实施中，公司注重流程规范，确保业务高效推进。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (',绵阳市科教创业园区,租赁和商务服务业,51-200人,2001-10-08,https://www.scmyns.cn/,764420463@qq.com,2026-03-31 09:37:38.911,91510700759729921R,/api/storage/objects/uploads/573728a4-a706-4ea0-8553-5435c329a1b3', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (14, '立信华晖（北京）企业管理有限公司立足北京深耕企业服务领域，主营企业管理咨询、数字化技术研发、财税顾问及商务配套服务。公司秉持诚信务实理念，依托专业团队与成熟服务体系，聚焦企业经营赋能，可精准提供合规高效、一体化定制解决方案。', '北京', '租赁和商务服务业-商务服务业-组织管理服务-其他组织管理服务', '51-200人', 2021, NULL, 'linweidongyt@126.com', '2026-03-31 09:40:41.297', '91110117MA04F6TDX0', NULL),
  (24, '北京市海淀区国有资产投资集团有限公司（简称海国投集团）是北京市海淀区人民政府国有资产监督管理委员会下属的国有独资有限责任公司，是海淀区国资委旗下规模最大的一级监管企业。公司成立于1992年，前身为北京市海淀区国有资产投资经营公司，于2011年改制为有限责任公司，2020年3月更名为现名。公司注册资本100亿元人民币，注册地位于北京市海淀区西四环北路9号鑫泰大厦三层，法定代表人为于志伟。作为海淀区重要的国有资产投资运营平台，其产业辐射城市服务、金融投资、低碳环保、文化教育、资产管理五大核心板块，并参与设立了中关村科学城科技成长基金等多只私募股权投资基金。', '北京市海淀区', NULL, '501-1000人', '2012年', 'http://www.hgtgroup.com.cn', NULL, '2026-03-31 09:54:27.257', '91110108599642586E', '/api/storage/objects/uploads/8646668b-0209-427c-9386-4165e1e9722f'),
  (13, '中央文化和旅游管理干部学院（中共文化和旅游部党校）是文化和旅游部直属事业单位，是文化和旅游系统干部人才教育培训的主渠道主阵地，是文化和旅游领域政策研究和决策咨询的重要智库平台。先后被确定为文化和旅游部对非培训基地、全国基层文化队伍培训基地、国家级专业技术人员继续教育基地、国家文物局文博人才培训基地以及商务部（国家国际发展合作署）对外援助人力资源开发合作项目承办单位等。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('学院立足文化建设和旅游发展实际，针对文化和旅游系统高水平干部队伍建设和高质量行业人才培养需求，充分利用文化旅游资源，形成具有文化和旅游特色的课程、师资、教材“三位一体”教学体系。累计开设特色课程1000余门，涵盖党的创新理论、国家重要战略及文化和旅游各个业务领域；在库师资3000余位，包括党政领导干部、知名专家学者、行业精英、一线能人等；编写、引进理论专著、实践手册、案例汇编等教材教辅近百种。学院广泛应用案例式、访谈式、体验式、情景式等特色教学方式，建有九大特色教学空间，涉及智慧党建、美丽中国、文旅融合、文化科技、美学美育、城市更新、乡村振兴、公共服务、媒体创新、对外文化交流等多个主题。学院围绕研究阐释习近平文化思想，聚焦文化和旅游领域重大理论和实践课题，开展各类专题研究和学术交流合作，完成文化和旅游部、相关国家部委、地方政府及文化和旅游部门等科研课题和委托项目近百项。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('学院同时开设全国文化和旅游干部网络学院，线上课程数量超2000门，注册学员1万余名，并为多个业务司局及部分省级文化和旅游部门开设网络学院分院，提供专题性、区域性定制化服务。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('学院拥有北京主院区和河北分院区两处场地，总占地面积240亩，建筑面积45000平方米。学院环境优美、交通便利、区位优势明显，基础设施齐全，包括教学楼、办公楼、报告厅、特色教学空间、文体中心、学员公寓、学员餐厅、运动场等10余处现代化教学和生活设施，目前可同时容纳460人在院培训。学院同时在山东、云南、浙江、福建、陕西、江西、新疆、辽宁等地设有培训基地，可满足京内外教学培训需要。,北京市大兴区,,,,https://cacta.cn/,,2026-03-31 10:15:04.084,12100000400963252Y,/api/storage/objects/uploads/672bf7e6-fe32-4c98-bd04-436f17263eca', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (15, '海亮教育科技服务集团隶属于世界500强企业海亮集团，创立于1995年，是学校教育与科技服务双轮驱动的领军企业之一。旗下拥有“海亮教育”“海亮科服”双核心品牌，聚焦“将乡村教育振兴作为永久的头等大事、构建教育生态圈、建设卓越教育高地”三大战略，致力于以科技和服务助推实现教育高质量发展，让每个生命出彩。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('“海亮教育”坚守“为党育人，为国育才”的发展使命，坚持“精品化、特色化、国际化”的办学定位，秉承“人皆有才、人人成才，让每个生命出彩”的核心理念，深度践行特色化分类办学和个性化教育，倾心打造30+高品质小初高学校，30+精品幼儿园，40+人工智能教育机构，及3家特殊教育机构，在校学生超6万人，是中国民办基础教育高质量发展的重要力量。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  ('“海亮科服”依托海亮教育三十年办学实践，自2021年创立以来，以智慧教育与平台服务双轮驱动，面向区域及学校提供融合科技产品和管理咨询的教育+AI整体解决方案，构建集科创、艺体、人文、国际等优质教育资源于一体的一站式服务平台，满足学生个性化发展需要，致力于推动基础教育全场景下的因材施教与高质量发展。凭借可复制、可验证的核心能力，海亮科服业务现已覆盖全国210余个区县，累计服务超千万人次，获得超120个深度服务县域的官方感谢信，已成为从实体办学入局教育科技、规模领先的标杆企业。,浙江省绍兴市诸暨市,教育,201-500人,2024,https://hailiangedu.com/,edu-hr@hailiang.com,2026-03-31 10:24:53.948,91330681MAE1F11T1Q,/api/storage/objects/uploads/00ab7f9b-6e5e-4b56-90ab-738b61e4615a', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (19, '北京叁叁好赞文化科技有限公司，以“用内容创造新可能”为特色，以有质感的内容驱动，深度策略挖掘，整合跨界资源，为品牌搭建一条富有文化感和口碑力的传播矩阵。团队核心主创团队来自网易、三联生活周刊及国际知名4A创意公司，为高端地产及生活方式品牌提供品牌传播服务。凭借具有文化感、洞察力、先锋性及高品质内容的稳定输出，为华润置地、中建智地、融科资讯中心（高端商业地产）、ASKO（瑞典奢品家电）等提供品牌服务，与此同时，连续四年参与北京市城市更新项目宣传片拍摄。公司拥有丰富的跨界资源，对高端品牌消费人群具有长期洞察力，擅长整合营销、策略创意、视频制作等，在品牌赋能、新媒体整合、社会化营销、先锋活动等领域多次打造行业经典标杆案例，并获得广告行业多个奖项认同', '北京', '广告营销、视频制作', '11-50人', '2020年4月14日', NULL, '920136064@qq.com', '2026-03-31 12:23:56.586', '91110302MA01QQ2DXA', '/api/storage/objects/uploads/fd3359fa-9f94-45c6-9285-018ca3045089'),
  (245, NULL, '北京市海淀区中关村东路', 'AI 教育  AI 漫剧   AIGC生态    IP孵化', '1-10人', 2022, NULL, '82506825@qq.com', '2026-04-08 03:29:27.806', ' 91110108MA7LA1DY7C', NULL);
