  (4, 1, '李林晓', 16619927190, NULL, NULL, '{"您的身份": "需求发布方", "是否已注册公司": "是", "参加本次活动目的": ["了解OPC落地政策", "寻找OPC创业生态支持", "与OPC企业座技术交流", "寻找需求场景", "发布需求场景"], "是否有注册落地意愿": "是", "您可以提供的主要产品或服务介绍（方便后续合作）": "1.创业者认知产品2.创业者心力提升培训3.应届生就业指导4.阳光读书5.高知女性心力提升。"}', NULL, '2026-04-16 08:17:27.918231'),
  (5, 1, '徐新', 15331826507, NULL, NULL, '{"您的身份": "需求发布方", "是否已注册公司": "否", "参加本次活动目的": ["寻找需求场景", "发布需求场景", "与OPC企业座技术交流"], "是否有注册落地意愿": "是", "您可以提供的主要产品或服务介绍（方便后续合作）": "我们在做一个AI驱动的市场测试工具，\\n\\n帮助海外品牌快速验证中国市场，\\n包括产品定位、KOL匹配和投放策略，\\n\\n目前在对接海外品牌和国内渠道，\\n做小规模测试和市场验证。"}', NULL, '2026-04-16 08:47:18.716527'),
  (6, 1, '周亮', 13683399723, 'zhou_liang1019@163.com', '北京一四银河科技有限公司', '{"您的身份": "技术供给方", "是否已注册公司": "是", "参加本次活动目的": ["了解OPC落地政策", "寻找OPC创业生态支持", "与OPC企业座技术交流"], "是否有注册落地意愿": "是", "您可以提供的主要产品或服务介绍（方便后续合作）": "智能运维、数据平台、系统建设"}', NULL, '2026-04-16 08:55:39.212519'),
  (7, 1, '史杰松', 19851292975, 'sjs345@163.com', '南京市夜鹭云人工智能科技有限公司', '{"您的身份": "技术供给方", "是否已注册公司": "是", "参加本次活动目的": ["了解OPC落地政策", "寻找OPC创业生态支持", "寻找需求场景", "发布需求场景", "与OPC企业座技术交流"], "是否有注册落地意愿": "是", "您可以提供的主要产品或服务介绍（方便后续合作）": "南京夜鹭云人工智能科技有限公司，是一家深耕营销策划、AI营销、营销培训三大核心领域的专业营销策划公司。我们以AI技术为核心驱动力，聚焦数字化营销全场景落地，构建“营销策划+AI工具+落地应用场景”一体化服务模型，为各行业客户提供全链路服务。凭借精准策略与技术落地实力，我们已服务自然堂、良品铺子、极草5X等众多知名品牌，打造了多个销量与口碑双丰收的标杆案例，成为南京及全国范围内极具影响力的南京营销策划公司。截止到2026年4月公司已获得AAA级信用等级证书，包括企业信用AAA级牌匾、AAA级 企业信用等级证书、AAA级 企业资信等级证书、AAA级 质量服务诚信企业、AAA级 重合同守信用企业、AAA级 诚信经营示范企业、AAA级 重质量守信用企业、AAA级 重服务守信用企业、AAA级 售后服务诚信企业等荣誉。\\n南京夜鹭云人工智能科技有限公司由兼具学术与行业视野的史杰松博士创立，他身为法国ISTEC高等商学院中方教授、工信部中小企业局专家组成员，提出的“AI营销五力模型”被纳入行业指南，为服务品质保驾护航。依托核心团队积淀，我们精准洞察各行业痛点，将AI技术与定制化营销策划深度融合，在快消品、农业、工业、大健康四大核心赛道打造了多个可复制的标杆案例，已为30余个行业头部企业铺就数字化转型之路，用实打实的业绩印证技术与营销的协同价值。\\n在快消品营销策划领域，我们以精细化策略精准破局，助力品牌实现销量与效率双重跃升。针对快消行业迭代快、竞争烈的特性，为未来生物科技搭建透明化智能数字工厂SaaS平台，同步配套全套爆品营销全案策划，从生产端到营销端全链路赋能，助力品牌快速抢占市场份额，最终达成22.1%的全网市占率，稳居细分领域前列；同时为极草5X提炼五大核心功效、为小刀酒设计异型瓶视觉符号、为秋林食品提出“糯+”战略，以差异化品牌策划精准抢占用户心智，全方位升级品牌竞争力。在农业营销策划赛道，我们打破传统农业品牌营销瓶颈，为博旺农业量身打造“品牌IP化+社交电商+私域流量精细化运营”三维增长模式。以短视频营销策划为核心引流抓手，精准匹配农业消费人群喜好，联动抖音直播场景实现“内容种草-直播转化”闭环，单场直播仅3小时销售额即突破百万，凭借持续的运营赋能，品牌天猫渠道累计销量超1.5亿袋，成功让传统农业品牌在电商赛道焕发新生；同时为新希望南山搭建产品溯源系统、为中航安盟构建农业保险体系，以产业链整合能力推动农业营销全链路升级。\\n在工业企业营销策划与大健康营销策划领域，南京夜鹭云人工智能科技有限公司以跨场景AI技术适配能力，打破行业营销边界。为约顿气膜设计专属数字孪生营销系统，通过数字化展示与沉浸式互动体验，解决工业产品可视化弱、沟通成本高的痛点，在成都体博会期间助力品牌海外订单实现300%爆发式增长，重塑工业产品营销新范式；针对大健康领域服务精细化需求，为三甲医院研发7×24小时AI导诊系统，通过智能分流、精准应答优化就医全流程，将服务满意度提升至98%，获得院方与患者双重认可；同时服务京东健康完善新零售布局，为泰国素万健康产业打造乳胶枕3D体态扫描推荐系统，精准匹配用户需求，将门店转化率提升至50%以上。南京夜鹭云人工智能科技有限公司 以全案营销策划为核心，围绕AI营销全案咨询、平台开发及营销培训三大板块，形成完善服务矩阵。自主研发的YeLu AI平台累计申请12项发明专利，为案例落地提供硬核技术支撑，成功为北京美家尽有家具电商构建“设计倒推生产”模式，精准匹配用户需求，推动复购率提升20%；同时联动文化IP与科技力量，为竹叶青规划数字化营销路径，为TX3打造本地化机顶盒解决方案，为泰国素万开展KOL场景化种草、恒大世界杯联动事件营销，多维度实现品牌声量与销量双增长。\\n在营销培训领域，南京夜鹭云人工智能科技有限公司深耕产学研用一体化建设，与多所高校共建AI商业实验室，搭建“一书一课一模型一系统”的AI教育体系，开发《AI营销师》职业认证课程，提供专业的数字化营销培训与营销培训课程，为行业培育复合型AI营销人才。同时以重构生态为目标，通过线上线下融合模式，整合直销与新零售资源，借助百家好与先锋书店跨界合作、莲花山AI文旅项目沉浸式体验等创新形式深化用户粘性，形成可规模化、标准化复制的行业解决方案。作为专注于AI赋能营销的先锋企业，南京夜鹭云人工智能科技有限公司 始终以“懂营销、会AI、有平台、能落地”为理念，聚焦营销策划核心，强化AI技术赋能，覆盖低成本获客方案、私域流量运营、短视频营销等多元场景。从快消品22.1%的全网市占率，到农业单场直播百万销售额，再到工业海外订单300%增长，我们用一个个标杆案例证明实力。未来，将继续以史杰松博士的行业理论为指引，深化技术研发与人才培育，为更多客户提供精准、高效、可落地的数字化营销解决方案，共赴数字化增长新征程。"}', NULL, '2026-04-16 09:13:47.402002'),
  (8, 1, '沐珩', 13522216112, '18803230443@163.com', NULL, '{"您的身份": "技术供给方", "是否已注册公司": "是", "参加本次活动目的": ["了解OPC落地政策", "寻找OPC创业生态支持", "寻找需求场景"], "是否有注册落地意愿": "是", "您可以提供的主要产品或服务介绍（方便后续合作）": "AI应用开发与智能体落地培训"}', NULL, '2026-04-16 11:49:54.527276'),
