  (11, 1, '谭奕瑞', 13910798509, 'tyr1@139.com', NULL, '{"您的身份": "技术供给方", "产业合作需求": "EMC 技术", "是否已注册公司": "否", "参加本次活动目的": ["寻找需求场景", "与OPC企业座技术交流"], "是否有注册落地意愿": "否", "您可以提供的主要产品或服务介绍（方便后续合作）": "EMC 技术"}', NULL, '2026-04-17 03:14:20.405414'),
  (12, 1, '孙廉焘', 17080153611, NULL, NULL, '{"您的身份": "技术供给方", "是否已注册公司": "否", "参加本次活动目的": ["了解OPC落地政策", "与OPC企业座技术交流"], "是否有注册落地意愿": "否", "您可以提供的主要产品或服务介绍（方便后续合作）": "工业物联网与边缘智能解决方案专家。拥有超过10年研发与系统集成经验，深耕工业物联网架构设计与边缘智能网关开发。精通工业规约及通信协议设计、驱动开发，擅长应对恶劣环境下的高可靠数据采集与传输。致力于构建高安全、全国产化、高可用的智能化基础设施。"}', NULL, '2026-04-17 03:57:53.118651');
